<?php
namespace App\Livewire\Members;
use App\Models\Teacher; use Livewire\Component; use Livewire\WithPagination;
class TeacherIndex extends Component {use WithPagination; public string $search='',$teacherNumber='',$fullName='',$position='',$status='active'; public bool $isActive=true;public ?int $editingId=null;public function updatedSearch(){ $this->resetPage();}public function edit(int $id){$x=Teacher::findOrFail($id);$this->editingId=$id;$this->teacherNumber=$x->teacher_number??'';$this->fullName=$x->full_name;$this->position=$x->position??'';$this->status=$x->status;$this->isActive=$x->is_active;}public function resetForm(){ $this->reset(['editingId','teacherNumber','fullName','position']);$this->status='active';$this->isActive=true;}public function save(){ $d=$this->validate(['teacherNumber'=>['nullable','string','max:100','unique:teachers,teacher_number,'.$this->editingId],'fullName'=>'required|string|max:255','position'=>'nullable|string|max:255','status'=>'required|in:active,inactive','isActive'=>'boolean']);Teacher::updateOrCreate(['id'=>$this->editingId],['teacher_number'=>$d['teacherNumber'],'full_name'=>$d['fullName'],'position'=>$d['position'],'status'=>$d['status'],'is_active'=>$d['isActive']]);$this->resetForm();session()->flash('success','Data guru berhasil disimpan.');}public function deactivate(int $id): void { Teacher::findOrFail($id)->update(['is_active'=>false]); session()->flash('success','Guru dinonaktifkan.'); } public function render(){return view('livewire.members.teacher-index',['teachers'=>Teacher::where('is_active',true)->when($this->search,fn($q)=>$q->where('teacher_number','like','%'.$this->search.'%')->orWhere('full_name','like','%'.$this->search.'%'))->latest()->paginate(10)])->layout('components.layouts.app',['heading'=>'Data Guru']);}}
